function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 1000) return 'queries needs 1 to 1000 values.';
  if ([...nums, ...queries].some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Every value is an integer from 1 to 10^9.';
  return null;
}

