function maximumProcessableQueries(nums, queries) {
  const n = nums.length;
  const step = (done, value) => (done < queries.length && value >= queries[done] ? done + 1 : done);
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let length = n - 1; length >= 1; length--) {
    for (let left = 0; left + length <= n; left++) {
      const right = left + length - 1;
      if (left > 0) {
        dp[left][right] = Math.max(dp[left][right], step(dp[left - 1][right], nums[left - 1]));
      }
      if (right < n - 1) {
        dp[left][right] = Math.max(dp[left][right], step(dp[left][right + 1], nums[right + 1]));
      }
    }
  }

  let best = 0;
  for (let i = 0; i < n; i++) {
    best = Math.max(best, step(dp[i][i], nums[i]));
  }
  return best;
}

