function maximumProcessableQueries(nums, queries) {
  const play = (kept, lo, hi, q) => {
    if (q === queries.length || lo > hi) return q;
    let result = q;
    if (kept[lo] >= queries[q]) result = Math.max(result, play(kept, lo + 1, hi, q + 1));
    if (kept[hi] >= queries[q]) result = Math.max(result, play(kept, lo, hi - 1, q + 1));
    return result;
  };
  let best = 0;
  for (let mask = 0; mask < (1 << nums.length); mask++) {
    const kept = nums.filter((_, index) => (mask >> index) & 1);
    best = Math.max(best, play(kept, 0, kept.length - 1, 0));
  }
  return best;
}

