function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = int(2, 7);
    const nums = Array.from({ length: int(1, 8) }, () => int(1, top));
    const queries = Array.from({ length: int(1, 8) }, () => int(1, top));
    return [nums, queries];
  }
  const top = [20, 1000, 1e9][int(0, 2)];
  const nums = Array.from({ length: int(900, 1000) }, () => int(1, top));
  const queries = Array.from({ length: int(900, 1000) }, () => int(1, top));
  if (rand() < 0.5) queries.sort((x, y) => x - y);
  return [nums, queries];
}
